import {exact,validateConfig} from './pinn-core.mjs';
const $=id=>document.getElementById(id),colors={nn:'#ffb06b',pinn:'#5ee4d0',exact:'#9aaabd'};
let worker=null,checkpoints=[],current=null,runs=[],replayTimer=null,busy=false;
const fmt=n=>Number.isFinite(n)?n.toExponential(2):'—';
function config(){return validateConfig({samples:+$('samples').value,noise:+$('noise').value,weight:+$('weight').value,steps:+$('steps').value,seed:+$('seed').value});}
function updateLabels(){$('samplesValue').value=$('samples').value;$('noiseValue').value=(+$('noise').value).toFixed(2);if(current&&!busy)$('trainStatus').textContent='Settings changed. Train again to apply; plots still show the previous run.';}
$('samples').oninput=updateLabels;$('noise').oninput=updateLabels;for(const id of ['weight','steps','seed'])$(id).oninput=updateLabels;
function surface(id){const el=$(id),b=el.getBoundingClientRect(),d=window.devicePixelRatio||1;if(!b.width||!b.height)return null;el.width=Math.round(b.width*d);el.height=Math.round(b.height*d);const c=el.getContext('2d');c.setTransform(d,0,0,d,0,0);c.font='12px sans-serif';return{c,w:b.width,h:b.height,el};}
function axes(s,xTitle,yTitle,ymin,ymax,log=false){const{c,w,h}=s;const p={l:50,r:16,t:25,b:38};const x=v=>p.l+v*(w-p.l-p.r),y=v=>p.t+(ymax-(log?Math.log10(Math.max(v,1e-10)):v))/(ymax-ymin)*(h-p.t-p.b);c.fillStyle='#99a9bc';c.fillText(yTitle,p.l,13);c.strokeStyle='#273444';c.lineWidth=1;c.setLineDash([]);for(let i=0;i<=4;i++){const v=ymin+(ymax-ymin)*i/4,Y=p.t+(1-i/4)*(h-p.t-p.b);c.beginPath();c.moveTo(p.l,Y);c.lineTo(w-p.r,Y);c.stroke();c.fillText(log?'1e'+(Number.isInteger(v)?v:v.toFixed(1)):v.toFixed(2),3,Y+4);}c.fillText(xTitle,w-p.r-c.measureText(xTitle).width,h-3);return{x,y,p};}
function curve(c,points,color,dash=[]){c.beginPath();for(let i=0;i<points.length;i++)i?c.lineTo(...points[i]):c.moveTo(...points[i]);c.strokeStyle=color;c.lineWidth=2;c.setLineDash(dash);c.stroke();c.setLineDash([]);}
function drawPrediction(){const s=surface('prediction');if(!s)return;const ti=+$('predictionTime').value,t=ti/20;const a=axes(s,'Position x','Concentration u',-.25,1.25);for(let i=0;i<=4;i++){s.c.fillStyle='#99a9bc';s.c.fillText((i/4).toFixed(2),a.x(i/4)-10,s.h-18);}curve(s.c,Array.from({length:128},(_,i)=>[a.x(i/127),a.y(exact(i/127,t))]),colors.exact,[5,4]);if(current)for(const key of ['nn','pinn'])curve(s.c,current[key].field.slice(ti*64,(ti+1)*64).map((v,i)=>[a.x((i+.5)/64),a.y(v)]),colors[key]);$('predictionTimeValue').value=`t = ${t.toFixed(2)}`;$('sliceSummary').textContent=`${t>.25?'Beyond':'Within'} the observation time range (0 ≤ t ≤ 0.25). ${current?'Profiles are predictions at training step '+current.step+'.':'Train to add network predictions.'}`;s.el.setAttribute('aria-label',`Concentration versus position at t=${t}, ${current?'network predictions at step '+current.step:'exact reference only'}`);}
function drawLoss(id,key){const s=surface(id);if(!s||!current)return;const data=checkpoints.filter(p=>p.step<=current.step);const vals=data.flatMap(p=>[p[key].l.data,p[key].l.initial,p[key].l.physics]);const low=Math.min(-3,Math.floor(Math.log10(Math.max(1e-10,Math.min(...vals))))),high=Math.max(0,Math.ceil(Math.log10(Math.max(...vals))));const a=axes(s,'Training step','Unweighted MSE · log scale',low,high,true);for(const [name,color]of[['data',colors.pinn],['initial',colors.nn],['physics','#b5a0fa']])curve(s.c,data.map(p=>[a.x(p.step/current.config.steps),a.y(p[key].l[name])]),color);for(let i=0;i<=4;i++){s.c.fillStyle='#99a9bc';s.c.fillText(String(Math.round(current.config.steps*i/4)),a.x(i/4)-8,s.h-18);}const l=current[key].l;$(`${key}LossValues`).textContent=`Data ${fmt(l.data)} · Initial ${fmt(l.initial)} · Equation ${fmt(l.physics)}`;s.el.setAttribute('aria-label',`${key} loss curves through step ${current.step}. Data ${fmt(l.data)}, initial ${fmt(l.initial)}, equation ${fmt(l.physics)}.`);}
function drawResidual(){const s=surface('residual');if(!s||!current)return;const key=$('residualModel').value,values=current[key].residual;const max=Math.max(1e-8,...current.nn.residual.map(Math.abs),...current.pinn.residual.map(Math.abs));const p={l:45,r:18,t:10,b:42},cw=s.w-p.l-p.r,ch=s.h-p.t-p.b;for(let ti=0;ti<=20;ti++)for(let xi=0;xi<64;xi++){const z=Math.min(1,Math.abs(values[ti*64+xi])/max);s.c.fillStyle=`rgb(${Math.round(16+239*z)},${Math.round(31+145*z)},${Math.round(47+60*z)})`;s.c.fillRect(p.l+xi*cw/64,p.t+(20-ti)*ch/21,cw/64+1,ch/21+1);}s.c.fillStyle='#99a9bc';s.c.fillText('t',12,p.t+8);for(let i=0;i<=4;i++){s.c.fillText((i/4).toFixed(2),5,p.t+(1-i/4)*ch+4);s.c.fillText((i/4).toFixed(2),p.l+i*cw-10,s.h-24);}s.c.fillText('Position x',s.w-80,s.h-5);s.c.strokeStyle='#fff';s.c.setLineDash([4,4]);s.c.beginPath();s.c.moveTo(p.l,p.t+.75*ch);s.c.lineTo(s.w-p.r,p.t+.75*ch);s.c.stroke();s.c.setLineDash([]);for(const o of current.observations){s.c.beginPath();s.c.arc(p.l+o.x*cw,p.t+(1-o.t)*ch,2,0,Math.PI*2);s.c.fillStyle='#fff';s.c.fill();}$('residualSummary').textContent=`Dark = 0 · Bright = ${fmt(max)}. Same color scale for both models. Dashed line: last observed time.`;s.el.setAttribute('aria-label',`${key} absolute equation residual over position and time, common scale 0 to ${fmt(max)}. ${current.observations.length} observation locations in the first quarter of time.`);}
function render(){drawPrediction();if(!current)return;$('diagnostics').hidden=false;$('nnError').textContent=fmt(current.nn.heldRMSE);$('pinnError').textContent=fmt(current.pinn.heldRMSE);$('trainingTime').textContent=((current.nnMs+current.pinnMs)/1000).toFixed(2)+' s';$('timeBreakdown').textContent=`NN ${(current.nnMs/1000).toFixed(2)} s · PINN ${(current.pinnMs/1000).toFixed(2)} s`;$('epochValue').value=`Step ${current.step}`;$('massSummary').textContent=`Maximum deviation from exact mass 0.5 over all time slices: ordinary NN ${fmt(current.nn.massDrift)}; PINN ${fmt(current.pinn.massDrift)}. Full-domain RMSE: NN ${fmt(current.nn.rmse)}; PINN ${fmt(current.pinn.rmse)}.`;drawLoss('nnLoss','nn');drawLoss('pinnLoss','pinn');drawResidual();}
function stopReplay(){clearInterval(replayTimer);replayTimer=null;$('replay').textContent='Replay training';}
function setBusy(value){busy=value;$('train').disabled=value;$('cancel').hidden=!value;for(const el of $('trainingForm').querySelectorAll('input,select'))el.disabled=value;$('replay').disabled=value||!checkpoints.length;$('epoch').disabled=value||!checkpoints.length;}
function addHistory(s){document.querySelector('.history-panel').hidden=false;runs.push(s);const tr=document.createElement('tr');for(const v of [s.config.seed,s.config.samples,s.config.noise,s.config.weight,s.step,fmt(s.nn.heldRMSE),fmt(s.pinn.heldRMSE)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('runHistory').append(tr);}
function train(){let p;try{p=config();}catch(e){$('trainStatus').textContent=e.message;return Promise.reject(e);}if(busy)return Promise.reject(Error('Training is already running.'));stopReplay();worker?.terminate();checkpoints=[];current=null;$('diagnostics').hidden=true;for(const id of ['nnError','pinnError','trainingTime'])$(id).textContent='—';$('timeBreakdown').textContent='NN + PINN; excludes plotting';drawPrediction();$('progress').max=p.steps;$('progress').value=0;$('epoch').value=0;setBusy(true);$('trainingBadge').textContent='Training';$('trainStatus').textContent='Training from identical weights. Each plotted checkpoint is a real optimization result.';worker=new Worker('./pinn-worker.js',{type:'module'});
 return new Promise((resolve,reject)=>{let finished=false;const fail=message=>{if(finished)return;finished=true;worker?.terminate();setBusy(false);$('trainingBadge').textContent='Stopped';$('trainStatus').textContent=message;reject(Error(message));};$('cancel').onclick=()=>fail('Training stopped. Any displayed checkpoint is a partial result; it is not added to completed runs.');worker.onerror=()=>fail('Training failed to load. Please reload and try again.');worker.onmessage=({data})=>{if(data.error){fail(data.error);return;}if(data.done){finished=true;setBusy(false);$('trainingBadge').textContent='Complete';$('trainStatus').textContent=`Completed ${p.steps.toLocaleString()} steps. Change the seed or replay how the predictions evolved.`;if(current)addHistory(current);resolve({seed:p.seed,step:current.step,nnRMSE:current.nn.heldRMSE,pinnRMSE:current.pinn.heldRMSE});return;}checkpoints.push(data);current=data;$('progress').value=data.step;$('epoch').max=checkpoints.length-1;$('epoch').value=checkpoints.length-1;render();};worker.postMessage(p);});}
$('trainingForm').onsubmit=e=>{e.preventDefault();train().catch(()=>{});};$('predictionTime').oninput=drawPrediction;$('residualModel').onchange=drawResidual;$('epoch').oninput=()=>{stopReplay();current=checkpoints[+$('epoch').value];render();};$('replay').onclick=()=>{if(replayTimer){stopReplay();return;}let i=0;$('replay').textContent='Pause replay';replayTimer=setInterval(()=>{current=checkpoints[i];$('epoch').value=i;render();i++;if(i>=checkpoints.length)stopReplay();},160);};
$('exportRun').onclick=()=>{if(!current)return;const payload={version:1,method:'32 tanh neurons, analytic parameter and input derivatives, Adam lr 0.003',equation:'u_t + 0.5 u_x - 0.01 u_xx = 0',domain:{x:[0,1],t:[0,1],observationTime:[0,.25]},boundary:'periodic by sin/cos input encoding in both models',initialSamples:32,collocationPerStep:48,noise:'six uniform samples, centered and scaled to requested standard deviation',seed:current.config.seed,checkpoint:current,trainingHistory:checkpoints.filter(s=>s.step<=current.step).map(s=>({step:s.step,nn:s.nn.l,pinn:s.pinn.l})),validation:'held-out times t>0.25, evaluated against exact pointwise solution',formallyVerified:false};const url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`pinn-seed-${current.config.seed}-step-${current.step}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(()=>render()).observe(document.querySelector('.pinn-results'));window.addEventListener('resize',render);drawPrediction();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'train_transport_pinn',title:'Train transport neural networks',description:'Run actual ordinary-NN and PINN training with identical initial conditions and return exact-solution errors. Changes visible training state.',inputSchema:{type:'object',properties:{samples:{type:'integer',minimum:4,maximum:64,multipleOf:4},noise:{type:'number',minimum:0,maximum:.1,multipleOf:.01},weight:{type:'number',enum:[0,.01,.1,1,10]},steps:{type:'integer',enum:[500,1000,2000,5000]},seed:{type:'integer',minimum:1,maximum:9999}},required:['samples','noise','weight','steps','seed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async p=>{validateConfig(p);if(busy)throw Error('Training is already running.');if(![0,.01,.1,1,10].includes(p.weight)||![500,1000,2000,5000].includes(p.steps)||p.samples%4||Math.abs(p.noise*100-Math.round(p.noise*100))>1e-8)throw Error('Choose settings supported by the visible controls.');for(const k of ['samples','noise','weight','steps','seed'])$(k).value=p[k];updateLabels();return train();}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
